INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'title', 'n.', '/ˈtaɪtl/', '题目;标题;名称', 'Look at the title before you read the whole passage.', '读全文之前先看标题。', 'Exploring English', 1, 0, 'senior', 'wordlist', 'required1', 'U2', 'the title of a passage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'unique', 'adj.', '/juˈniːk/', '独一无二的;独特的', 'English is a unique language full of surprises.', '英语是一门充满惊喜的独特语言。', 'Exploring English', 2, 0, 'senior', 'wordlist', 'required1', 'U2', 'a unique language', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'creative', 'adj.', '/kriˈeɪtɪv/', '创造性的;有创意的', 'Try a creative way to remember new English words.', '试试用有创意的方法记英语单词。', 'Exploring English', 3, 0, 'senior', 'wordlist', 'required1', 'U2', 'a creative way', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'creativity', 'n.', '/ˌkriːeɪˈtɪvəti/', '创造力;创造性', 'English reflects the creativity of the people who use it.', '英语反映了使用它的人们的创造力。', 'Exploring English', 4, 0, 'senior', 'wordlist', 'required1', 'U2', 'the creativity of people', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reflect', 'v.', '/rɪˈflekt/', '反映;显示;表现', 'The words we choose often reflect the way we think.', '我们选用的词常常反映我们思考的方式。', 'Exploring English', 5, 0, 'senior', 'wordlist', 'required1', 'U2', 'reflect the culture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'type', 'n.', '/taɪp/', '类型;种类', 'There are several types of word formation in English.', '英语里有好几种构词法类型。', 'Exploring English', 6, 0, 'senior', 'wordlist', 'required1', 'U2', 'a type of word', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'unfamiliar', 'adj.', '/ˌʌnfəˈmɪliə/', '不熟悉的;陌生的', 'When you meet an unfamiliar word, try to guess its meaning.', '遇到陌生单词时,试着猜出它的意思。', 'Exploring English', 7, 0, 'senior', 'wordlist', 'required1', 'U2', 'an unfamiliar word', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'contact', 'v.', '/ˈkɒntækt/', '联系;联络', 'A penfriend is a friend you contact by writing letters.', '笔友是你通过写信联系的朋友。', 'Exploring English', 8, 0, 'senior', 'wordlist', 'required1', 'U2', 'contact a friend', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'organisation', 'n.', '/ˌɔːɡənaɪˈzeɪʃn/', '组织;团体;机构', 'WTO is short for the World Trade Organisation.', 'WTO 是世界贸易组织的缩写。', 'Exploring English', 9, 0, 'senior', 'wordlist', 'required1', 'U2', 'an international organisation', '美式拼 organization', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'likely', 'adj.', '/ˈlaɪkli/', '可能的;很可能发生的', 'A word known by many people is likely to enter the dictionary.', '为众人所知的词很可能被收入词典。', 'Exploring English', 10, 0, 'senior', 'wordlist', 'required1', 'U2', 'be likely to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confusing', 'adj.', '/kənˈfjuːzɪŋ/', '令人困惑的;难懂的', 'Even small words can be confusing for English learners.', '即使小词也可能让英语学习者困惑。', 'Exploring English', 11, 0, 'senior', 'wordlist', 'required1', 'U2', 'a confusing word', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'context', 'n.', '/ˈkɒntekst/', '上下文;语境', 'You can often guess a word''s meaning from the context.', '你常常能从语境猜出一个词的意思。', 'Exploring English', 12, 0, 'senior', 'wordlist', 'required1', 'U2', 'from the context', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'visible', 'adj.', '/ˈvɪzəbl/', '看得见的;可见的', 'When the stars are out, they are visible in the night sky.', '星星出来时,在夜空中清晰可见。', 'Exploring English', 13, 0, 'senior', 'wordlist', 'required1', 'U2', 'clearly visible', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'alarm', 'n.', '/əˈlɑːm/', '警报器;闹钟', 'An alarm is only heard once it goes off.', '警报器只有响起来才听得到。', 'Exploring English', 14, 0, 'senior', 'wordlist', 'required1', 'U2', 'a fire alarm', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'behaviour', 'n.', '/bɪˈheɪvjə/', '举止;行为', 'Shameless and shameful behaviour can mean almost the same thing.', 'shameless 和 shameful 形容的行为几乎一样。', 'Exploring English', 15, 0, 'senior', 'wordlist', 'required1', 'U2', 'good behaviour', '美式拼 behavior', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'opposing', 'adj.', '/əˈpəʊzɪŋ/', '相反的;对立的', '"Hardly" and "softly" are not an opposing pair, though they look like one.', 'hardly 和 softly 看似相反,其实并不是一对反义词。', 'Exploring English', 16, 0, 'senior', 'wordlist', 'required1', 'U2', 'an opposing pair', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sculpt', 'v.', '/skʌlpt/', '雕刻;雕塑', 'We sculpt a sculpture but we take a photo.', '我们 sculpt 出一件雕塑,却是 take 一张照片。', 'Exploring English', 17, 0, 'senior', 'wordlist', 'required1', 'U2', 'sculpt a statue', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sculpture', 'n.', '/ˈskʌlptʃə/', '雕塑;雕刻作品', 'The artist made a beautiful sculpture out of stone.', '那位艺术家用石头做出了一件美丽的雕塑。', 'Exploring English', 18, 0, 'senior', 'wordlist', 'required1', 'U2', 'a stone sculpture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ham', 'n.', '/hæm/', '火腿', 'Funnily enough, there is no ham in a hamburger.', '有趣的是,hamburger(汉堡)里并没有 ham(火腿)。', 'Exploring English', 19, 0, 'senior', 'wordlist', 'required1', 'U2', 'a ham sandwich', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'homesick', 'adj.', '/ˈhəʊmsɪk/', '想家的;思乡的', 'Strangely, we don''t feel homesick when we get back home.', '奇怪的是,回到家时我们并不感到 homesick。', 'Exploring English', 20, 0, 'senior', 'wordlist', 'required1', 'U2', 'feel homesick', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'subway', 'n.', '/ˈsʌbweɪ/', '(美)地铁', 'Americans take the subway, but the British travel on the underground.', '美国人坐 subway(地铁),英国人坐 underground。', 'Exploring English', 21, 0, 'senior', 'wordlist', 'required1', 'U2', 'take the subway', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'highway', 'n.', '/ˈhaɪweɪ/', '(美)公路;大路', 'In the US people drive along the highway, while in the UK they use the motorway.', '在美国人们沿 highway 开车,在英国则走 motorway。', 'Exploring English', 22, 0, 'senior', 'wordlist', 'required1', 'U2', 'drive along the highway', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gas', 'n.', '/ɡæs/', '(美)汽油', 'Americans put gas in their cars, but the British call it petrol.', '美国人给车加 gas,英国人却叫 petrol。', 'Exploring English', 23, 0, 'senior', 'wordlist', 'required1', 'U2', 'put gas in the car', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'petrol', 'n.', '/ˈpetrəl/', '(英)汽油', 'In the UK, drivers put petrol in their cars.', '在英国,司机给车加 petrol(汽油)。', 'Exploring English', 24, 0, 'senior', 'wordlist', 'required1', 'U2', 'buy some petrol', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'apartment', 'n.', '/əˈpɑːtmənt/', '(美)公寓;一套住房', 'Americans live in an apartment, while the British live in a flat.', '美国人住 apartment,英国人住 flat。', 'Exploring English', 25, 0, 'senior', 'wordlist', 'required1', 'U2', 'live in an apartment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flat', 'n.', '/flæt/', '(英)公寓;一套住房', 'She rents a small flat near the city centre.', '她在市中心附近租了一套小 flat(公寓)。', 'Exploring English', 26, 0, 'senior', 'wordlist', 'required1', 'U2', 'a small flat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'downtown', 'adj.', '/ˌdaʊnˈtaʊn/', '市中心的;闹市区的', 'I went to a downtown shopping centre to buy some winter boots.', '我去市中心的购物中心买冬靴。', 'Exploring English', 27, 0, 'senior', 'wordlist', 'required1', 'U2', 'a downtown shop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'entrance', 'n.', '/ˈentrəns/', '入口;大门口', 'I asked a lady at the entrance where the shoe section was.', '我在入口处问一位女士鞋区在哪里。', 'Exploring English', 28, 0, 'senior', 'wordlist', 'required1', 'U2', 'at the entrance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'section', 'n.', '/ˈsekʃn/', '区域;部分', 'The shoe section turned out to be downstairs, not upstairs.', '鞋区原来在楼下,而不是楼上。', 'Exploring English', 29, 0, 'senior', 'wordlist', 'required1', 'U2', 'the shoe section', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exit', 'n.', '/ˈeksɪt/', '出口', 'While looking for the exit, I finally saw the shoes.', '在找出口时,我终于看到了那些鞋。', 'Exploring English', 30, 0, 'senior', 'wordlist', 'required1', 'U2', 'look for the exit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'downstairs', 'adv.', '/ˌdaʊnˈsteəz/', '在楼下;往楼下', 'The shoes were actually sold downstairs on the ground floor.', '鞋其实是在楼下的一层卖的。', 'Exploring English', 31, 0, 'senior', 'wordlist', 'required1', 'U2', 'go downstairs', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'boot', 'n.', '/buːt/', '靴子', 'She visited New York to buy some warm winter boots.', '她去纽约买几双暖和的冬靴。', 'Exploring English', 32, 0, 'senior', 'wordlist', 'required1', 'U2', 'winter boots', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'frog', 'n.', '/frɒɡ/', '青蛙', '"A frog in one''s throat" means you can hardly speak, not that you ate a frog.', '"喉咙里有只青蛙"指说话困难,而不是真吃了 frog。', 'Exploring English', 33, 0, 'senior', 'wordlist', 'required1', 'U2', 'a frog in one''s throat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'odd', 'adj.', '/ɒd/', '奇怪的;古怪的', 'I found it very odd that he called his kind grandfather "wicked".', '他把和蔼的祖父说成"wicked",我觉得很 odd(奇怪)。', 'Exploring English', 34, 0, 'senior', 'wordlist', 'required1', 'U2', 'feel odd', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'negative', 'adj.', '/ˈneɡətɪv/', '消极的;负面的', 'Why would my friend use a negative word about such a nice man?', '我朋友为什么用一个负面的词来形容这么好的人?', 'Exploring English', 35, 0, 'senior', 'wordlist', 'required1', 'U2', 'a negative word', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'comment', 'n.', '/ˈkɒment/', '评论;意见', 'I was looking forward to a positive comment on my paper.', '我盼着论文得到一句正面的评论。', 'Exploring English', 36, 0, 'senior', 'wordlist', 'required1', 'U2', 'a positive comment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'error', 'n.', '/ˈerə/', '错误;差错', 'There weren''t any errors in my English paper at all.', '我的英语论文里一个错误都没有。', 'Exploring English', 37, 0, 'senior', 'wordlist', 'required1', 'U2', 'make an error', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'remind', 'v.', '/rɪˈmaɪnd/', '提醒;使想起', 'These funny stories remind us how strange English can be.', '这些有趣的故事提醒我们英语有多奇怪。', 'Exploring English', 38, 0, 'senior', 'wordlist', 'required1', 'U2', 'remind sb of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rather', 'adv.', '/ˈrɑːðə/', '相当;颇;有点儿', 'Classroom English is often rather different from real-world English.', '课堂英语常常和真实英语相当不同。', 'Exploring English', 39, 0, 'senior', 'wordlist', 'required1', 'U2', 'rather different', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'resource', 'n.', '/rɪˈzɔːs/', '资源;资料', 'Online forums can be a very useful learning resource.', '在线论坛可以是非常有用的学习资源。', 'Exploring English', 40, 0, 'senior', 'wordlist', 'required1', 'U2', 'a learning resource', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'misadventure', 'n.', '/ˌmɪsədˈventʃə/', '倒霉的经历;不幸事故', 'Each post shared a funny misadventure with the English language.', '每个帖子都分享了一段和英语有关的倒霉趣事。', 'Exploring English', 41, 0, 'senior', 'wordlist', 'required1', 'U2', 'a small misadventure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'actually', 'adv.', '/ˈæktʃuəli/', '事实上;实际上', 'In British English, "first floor" actually means the floor above the ground.', '在英式英语里,first floor 实际上指地面以上的一层。', 'Exploring English', 42, 0, 'senior', 'wordlist', 'required1', 'U2', 'actually mean', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'intend', 'v.', '/ɪnˈtend/', '打算;计划;意图', 'Make sure your abbreviations say what you intend to say.', '确保你的缩写表达的正是你打算说的意思。', 'Exploring English', 43, 0, 'senior', 'wordlist', 'required1', 'U2', 'intend to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'informal', 'adj.', '/ɪnˈfɔːml/', '非正式的;随便的', '"Wicked" can be an informal word that means "fantastic".', 'wicked 可以是个非正式的词,意思是"棒极了"。', 'Exploring English', 44, 0, 'senior', 'wordlist', 'required1', 'U2', 'informal language', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recognise', 'v.', '/ˈrekəɡnaɪz/', '认出;辨认;承认', 'By now I can recognise the differences between American and British English.', '现在我能辨认出美式和英式英语的区别了。', 'Exploring English', 45, 0, 'senior', 'wordlist', 'required1', 'U2', 'recognise the differences', '美式拼 recognize', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'base', 'v.', '/beɪs/', '以……为基础;基于', 'We can base a new word on a simpler word we already know.', '我们可以以已知的简单词为基础造出新词。', 'Exploring English', 46, 0, 'senior', 'wordlist', 'required1', 'U2', 'base sth on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'aware', 'adj.', '/əˈweə/', '意识到的;明白的', 'Good learners are aware of the cultural differences behind words.', '好的学习者会意识到词语背后的文化差异。', 'Exploring English', 47, 0, 'senior', 'wordlist', 'required1', 'U2', 'be aware of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'addition', 'n.', '/əˈdɪʃn/', '增加物;新增内容;加法', '"Selfie" is a recent addition to English dictionaries.', 'selfie 是英语词典里新增的词。', 'Exploring English', 48, 0, 'senior', 'wordlist', 'required1', 'U2', 'a new addition', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u2.01', '①派生:加前缀/后缀(un-/in-/im- 表否定;-less/-ful;-ment/-ity/-ness;-ly;-ive)', 'A2', 10, '外研社版必修第一册 U2 — 给单词加前缀或后缀可得到意义或词性不同的新词:un-/in-/im- 多表否定(correct→incorrect);-less 表''没有''、-ful 表''充满''(harmless/harmful);-ment/-ity/-ness 多构成名词;-ly 多构成副词。按语境选意义和形式都对的派生词。', 1, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u2.02', '②合成:把两个词合成一个新词(homesick / homework / blackboard / subway 等)', 'A2', 10, '外研社版必修第一册 U2 — 把两个(或更多)简单词合在一起构成合成词,意思常可从两部分推出:home+sick=homesick(想家),black+board=blackboard(黑板),sub+way=subway(地铁)。按语境选意思贴切的那个合成词。', 2, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u2.03', '③转化:同一个词不变形,用作不同词性(名词/形容词→动词)', 'A2', 10, '外研社版必修第一册 U2 — 有些名词或形容词不改变拼写就能用作动词:water(水→浇水)、name(名字→命名)、calm(平静的→使平静)。转化后仍按句子需要选正确的动词形式;to / 情态动词 / 祈使句后用动词原形。', 3, 'required1', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'If a piece of information is not correct, we say it is ____.', 'incorrect', 'correctly', 'correction', 'corrects', 'A', '表示''不正确''要在 correct 前加否定前缀 in-,且此处需形容词 → incorrect。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'An action that does no harm at all is completely ____.', 'harmful', 'harmless', 'harming', 'harmed', 'B', '''没有伤害''用后缀 -less;harmful 是''有害的''意思相反 → harmless。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'She failed the exam, so she is feeling quite ____ about it today.', 'happily', 'happiness', 'unhappy', 'happier', 'C', '表示''不高兴''在 happy 前加 un-,此处需形容词 → unhappy。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'After a year of practice, he has made great ____ in spoken English.', 'improve', 'improving', 'improved', 'improvement', 'D', 'great 后需名词,improve 加 -ment 构成名词 → improvement。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'These two words look so alike that they are really ____.', 'confusing', 'confuse', 'confusion', 'confused', 'A', '形容事物''令人困惑''用 -ing 形容词;confused 指人感到困惑 → confusing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'I have just arrived, so all these school rules are still ____ to me.', 'familiarly', 'unfamiliar', 'familiarity', 'familiarize', 'B', '表示''不熟悉的''需 un- 前缀的形容词 → unfamiliar。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'On a clear night, thousands of stars are easily ____ to the eye.', 'visibly', 'vision', 'visible', 'visit', 'C', 'be 后需形容词''看得见的'' → visible。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'In the thick fog, the tall mountains were almost ____.', 'unvisible', 'disvisible', 'nonvisible', 'invisible', 'D', 'visible 的否定前缀是 in-,其余前缀搭配不成词 → invisible。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'Choosing the right words well shows a person''s ____.', 'creativity', 'creative', 'create', 'creatively', 'A', 'person''s 后需名词,create 加 -ity 构成名词 → creativity。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'He found a very ____ way to memorise long English words.', 'creativity', 'creative', 'create', 'creatively', 'B', 'way 前需形容词 → creative。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'The whole class showed great ____ when the results came out.', 'excite', 'exciting', 'excitement', 'excited', 'C', 'great 后需名词,excite 加 -ment → excitement。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'Such rude ____ in the library surprised everyone around.', 'behave', 'behaving', 'behaved', 'behaviour', 'D', 'rude 后需名词,behave 的名词是 behaviour → behaviour。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'The guide was patient and very ____ to every visitor.', 'helpful', 'helpless', 'helping', 'helped', 'A', '表示''乐于帮助、有用的''用 -ful;helpless 是''无助的''意思相反 → helpful。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'Without a map or a phone, the lost tourists felt completely ____.', 'helpful', 'helpless', 'helping', 'helped', 'B', '表示''无助的、无能为力的''用 -less → helpless。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'It is almost ____ to learn every single word in a dictionary.', 'unpossible', 'dispossible', 'impossible', 'impossibly', 'C', 'possible 的否定前缀是 im-,此处需形容词;impossibly 是副词 → impossible。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'Knowing about word formation is very ____ when you read.', 'useless', 'using', 'used', 'useful', 'D', '表示''有用的''用 -ful → useful。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'A dictionary that you never open is almost ____.', 'useless', 'useful', 'using', 'used', 'A', '表示''没用的''用 -less → useless。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'The teacher explained the rule clearly and ____.', 'simple', 'simply', 'simplify', 'simplicity', 'B', '与 clearly 并列需副词,simple 加 -ly → simply。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'Add the ending ''-ly'' to ''quick'' and you get the adverb ____.', 'quickness', 'quicken', 'quickly', 'quicker', 'C', 'quick 加副词后缀 -ly → quickly。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.01'), 'Learning where a word comes from makes it far more ____.', 'meaningless', 'meaning', 'meant', 'meaningful', 'D', '表示''有意义的''用 -ful,more 后需形容词 → meaningful。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'Travelling by ship for the first time, she soon began to feel ____.', 'seasick', 'homesick', 'carsick', 'airsick', 'A', '在海上(sea)晕的是 seasick(晕船)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'After a month studying abroad, the boy missed his family and felt ____.', 'seasick', 'homesick', 'airsick', 'carsick', 'B', '想家(home)是 homesick。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'Long flights make some passengers feel ____ high in the sky.', 'seasick', 'carsick', 'airsick', 'homesick', 'C', '在空中(air)晕的是 airsick(晕机)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'On the bumpy mountain road, the children started to feel ____.', 'seasick', 'airsick', 'homesick', 'carsick', 'D', '在车里(car)晕的是 carsick(晕车)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'A ____ is someone you keep in touch with by writing letters.', 'penfriend', 'classmate', 'teammate', 'neighbour', 'A', '用笔(pen)联系的朋友是 penfriend(笔友)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'We must finish our ____ at home before the next English lesson.', 'housework', 'homework', 'classroom', 'weekend', 'B', '在家做的功课是 homework。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'My mother asked me to help with the ____, such as washing the dishes.', 'homework', 'classwork', 'housework', 'network', 'C', '做家务(house)是 housework。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'Saturday and Sunday together make up the ____.', 'weekday', 'holiday', 'midday', 'weekend', 'D', '一周的末尾(week+end)是 weekend(周末)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'Green plants need plenty of warm ____ to grow well.', 'sunshine', 'moonlight', 'starlight', 'candlelight', 'A', '植物需要阳光,sun+shine=sunshine。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'The teacher wrote the new words on the ____ at the front of the room.', 'cardboard', 'blackboard', 'keyboard', 'surfboard', 'B', '教室前写字的黑板是 blackboard。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'I copied every new English word neatly into my ____.', 'cookbook', 'handbook', 'notebook', 'phonebook', 'C', '记笔记的本子是 notebook(note+book)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'It suddenly began to rain, so I quickly put on my ____.', 'overcoat', 'rainbow', 'snowman', 'raincoat', 'D', '挡雨的外套是 raincoat(rain+coat)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'After the storm passed, a colourful ____ appeared in the sky.', 'rainbow', 'raincoat', 'sunshine', 'snowball', 'A', '雨后天空出现的是 rainbow(彩虹)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'Cars and buses speed along the wide ____ between the two cities.', 'doorway', 'highway', 'hallway', 'stairway', 'B', '城际间的宽阔大路是 highway(high+way)。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'In a busy city, many people travel underground by ____.', 'highway', 'runway', 'subway', 'driveway', 'C', '地下(sub)的路是 subway(地铁)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'I clean my teeth every morning with a ____.', 'hairbrush', 'paintbrush', 'nailbrush', 'toothbrush', 'D', '刷牙(tooth)用的刷子是 toothbrush。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'We read about the latest news in this morning''s ____.', 'newspaper', 'wallpaper', 'sandpaper', 'notepaper', 'A', '登载新闻(news)的纸是 newspaper(报纸)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'My grandparents still live in my quiet little ____ in the south.', 'downtown', 'hometown', 'homeland', 'homework', 'B', '出生长大的小镇是 hometown(home+town,家乡)。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'In summer she grows tall yellow ____ along the garden wall.', 'sunglasses', 'sunrises', 'sunflowers', 'sunbeams', 'C', '向着太阳(sun)的花是 sunflower(向日葵)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.02'), 'After class, the boys kicked the ____ around the playground.', 'basketball', 'baseball', 'volleyball', 'football', 'D', '用脚(foot)踢的球是 football(足球)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Remember to ____ the flowers in the garden every morning.', 'water', 'waters', 'watered', 'watering', 'A', 'water 由名词转化作动词''浇水'';to 后用动词原形 → water。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Could you please ____ me that English dictionary on the shelf?', 'hands', 'hand', 'handed', 'handing', 'B', 'hand 由名词转化作动词''递'';情态动词后用原形 → hand。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'They have decided to ____ their new baby after her grandmother.', 'names', 'named', 'name', 'naming', 'C', 'name 由名词转化作动词''给……取名'';to 后用原形 → name。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Don''t forget to ____ the front door when you leave the house.', 'locks', 'locked', 'locking', 'lock', 'D', 'lock 由名词转化作动词''锁'';to 后用原形 → lock。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'I need to ____ a table for four at the restaurant tonight.', 'book', 'books', 'booked', 'booking', 'A', 'book 由名词转化作动词''预订'';to 后用原形 → book。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'I will ____ you the new English word as soon as I get home.', 'texts', 'text', 'texted', 'texting', 'B', 'text 由名词转化作动词''发短信'';will 后用原形 → text。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Please ____ me the file before noon so I can read it.', 'emails', 'emailed', 'email', 'emailing', 'C', 'email 由名词转化作动词''发邮件'';祈使句用原形 → email。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'I''ll ____ you tonight to talk about our English project.', 'phones', 'phoned', 'phoning', 'phone', 'D', 'phone 由名词转化作动词''打电话'';will 后用原形 → phone。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'We plan to ____ our house a bright shade of blue this summer.', 'paint', 'paints', 'painted', 'painting', 'A', 'paint 由名词转化作动词''刷漆、涂'';to 后用原形 → paint。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Dark clouds gathered, and soon it began to ____ heavily.', 'rains', 'rain', 'rained', 'raining', 'B', 'rain 由名词转化作动词''下雨'';to 后用原形 → rain。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'It is so cold that it is going to ____ in the mountains tonight.', 'snows', 'snowed', 'snow', 'snowing', 'C', 'snow 由名词转化作动词''下雪'';be going to 后用原形 → snow。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Bright lamps will ____ the whole stage during the evening show.', 'lights', 'lighted', 'lighting', 'light', 'D', 'light 由名词转化作动词''照亮'';will 后用原形 → light。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'The head teacher will ____ the first prize to the winner tonight.', 'present', 'presents', 'presented', 'presenting', 'A', 'present 由名词转化作动词''颁发、赠送'';will 后用原形 → present。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'The teacher asked us to ____ the new words in real sentences.', 'uses', 'use', 'used', 'using', 'B', 'use 作动词''使用'';to 后用原形 → use。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Please ____ me at once if I make any mistakes in my English.', 'corrects', 'corrected', 'correct', 'correcting', 'C', 'correct 由形容词转化作动词''改正'';祈使句用原形 → correct。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Take a deep breath and try to ____ down before the speech.', 'calms', 'calmed', 'calming', 'calm', 'D', 'calm 由形容词转化作动词''使平静'';to 后用原形 → calm。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Hang the wet clothes outside to ____ them in the warm sun.', 'dry', 'dries', 'dried', 'drying', 'A', 'dry 由形容词转化作动词''弄干'';to 后用原形 → dry。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'I really need to ____ my messy room this weekend.', 'cleans', 'clean', 'cleaned', 'cleaning', 'B', 'clean 由形容词转化作动词''打扫'';to 后用原形 → clean。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Come inside and ____ yourself by the warm fire.', 'warms', 'warmed', 'warm', 'warming', 'C', 'warm 由形容词转化作动词''使暖和'';祈使句用原形 → warm。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U2' AND code='f1u2.03'), 'Please ____ the box completely before you pack the books.', 'empties', 'emptied', 'emptying', 'empty', 'D', 'empty 由形容词转化作动词''倒空'';祈使句用原形 → empty。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Why English Can Seem Crazy', 'Have you ever wondered why English can be so strange to learn? One father did not think about it until his young son asked whether there was ham inside a hamburger. There isn''t. In the same way, there is no egg in an eggplant, and neither pine nor apple in a pineapple. These funny facts show how playful the language can be. We sculpt a sculpture and paint a painting, yet we simply take a photo. We travel in a car or a taxi, but on a bus or a train. People can feel seasick at sea and airsick in the air, but no one feels homesick after returning home. Even opposites are puzzling: if an action that causes no harm is harmless, why are shameless and shameful behaviour almost the same? English was created by people, not by machines, and that is exactly why it is full of such surprises.', '说明·英语为何看似古怪', 151, '[{"q":"What first made the father think about how strange English is?","answer":"A","options":["His son''s question about ham in a hamburger.","A lesson he taught at school.","A book he read about cooking.","A trip he took on a bus."],"explanation":"原文开头说儿子问 hamburger 里有没有 ham 才让父亲开始想这个问题,为转述。"},{"q":"According to the passage, which pair behaves in a surprising way?","answer":"B","options":["''Sea'' and ''air'' mean the same thing.","Both ''shameless'' and ''shameful'' describe almost the same behaviour.","''Car'' and ''taxi'' are opposites.","''Photo'' and ''painting'' are made the same way."],"explanation":"原文指出 shameless 和 shameful 形容的行为几乎一样,令人困惑,为转述。"},{"q":"Why does the writer say English is full of surprises?","answer":"A","options":["Because it was made by people rather than machines.","Because it has very few words.","Because no one really speaks it.","Because computers invented it."],"explanation":"末句说英语是人而非机器创造的,故充满惊喜,为转述。"}]'::jsonb, '[{"word":"hamburger","cn":"汉堡包"},{"word":"eggplant","cn":"茄子"},{"word":"harmless","cn":"无害的"}]'::jsonb, 2, 'required1', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Two Kinds of English', 'American English is now used all over the world, but it is not quite the same as British English. The two differ mostly in spelling and in everyday words. Long ago, Noah Webster made one of America''s first dictionaries and changed many ''-re'' endings to ''-er'', which is why the British ''theatre'' became the American ''theater''. The differences in vocabulary can be even more surprising. Americans put gas in their cars and drive along the highway, while British drivers use petrol and the motorway. Americans take the elevator to the top floor, but the British take the lift. In the United States people ride the subway, yet in Britain they travel on the underground. An American lives in an apartment; a British person lives in a flat. Luckily, this rarely causes real trouble, because people from the two countries can usually understand each other from the context. Still, they enjoy a friendly argument about which word is ''right''.', '说明·英式与美式英语', 158, '[{"q":"In what two ways do British and American English differ most?","answer":"B","options":["In grammar and in pronunciation only.","Mainly in their spelling and their everyday vocabulary.","In the number of letters used.","In the way questions are asked."],"explanation":"原文说两者差别主要在拼写和日常词汇,为转述。"},{"q":"What did Noah Webster do to American spelling?","answer":"C","options":["He removed all silent letters.","He added an ''e'' to every word.","He changed many ''-re'' endings into ''-er''.","He kept it exactly like British spelling."],"explanation":"原文说 Webster 把许多 -re 结尾改成 -er,为转述。"},{"q":"Why do these word differences rarely cause real problems?","answer":"D","options":["Everyone learns both kinds at school.","The two countries never speak to each other.","Dictionaries are not allowed.","People can usually work out the meaning from the situation."],"explanation":"原文说人们通常能从语境互相理解,为转述。"}]'::jsonb, '[{"word":"elevator","cn":"(美)电梯"},{"word":"motorway","cn":"(英)高速公路"}]'::jsonb, 2, 'required1', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'How New Words Are Built', 'When you open a dictionary, you often come across words you have never seen. This can feel a little scary, but many of these words are simply built from simpler ones. There are several common ways to make new words. The first is to join two words together, so ''pen'' and ''friend'' become ''penfriend'', and ''home'' and ''work'' become ''homework''. A second way is to add a prefix or a suffix. The prefixes ''un-'' and ''in-'' usually make a word mean its opposite, so ''correct'' becomes ''incorrect''. The endings ''-ment'' and ''-ness'' often turn a word into a noun, as when ''improve'' becomes ''improvement''. A third way is to use the same word as a different part of speech: we can ''calm'' someone down, or ''water'' the plants. Sometimes we even shorten a long name, so ''as soon as possible'' becomes ''asap''. You cannot know every word, but understanding these patterns helps you guess their meanings.', '说明·构词法', 156, '[{"q":"What does the writer say about new words in a dictionary?","answer":"A","options":["Many of them are made out of simpler words.","They have no meaning at all.","They cannot be understood by anyone.","They are all borrowed from other languages."],"explanation":"原文说很多生词其实由更简单的词构成,为转述。"},{"q":"What usually happens when you add ''un-'' or ''in-'' to a word?","answer":"B","options":["The word becomes a verb.","The word comes to mean the opposite.","The word loses all meaning.","The word becomes a name."],"explanation":"原文说 un-/in- 通常使词义相反,为转述。"},{"q":"Why is it useful to understand these word-building patterns?","answer":"C","options":["They let you avoid reading completely.","They make every word exactly the same.","They help you guess the meanings of new words.","They replace the need for a dictionary forever."],"explanation":"末句说懂得这些规律有助于猜测词义,为转述。"}]'::jsonb, '[{"word":"prefix","cn":"前缀"},{"word":"suffix","cn":"后缀"}]'::jsonb, 2, 'required1', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Words of the Internet Age', 'Every year, dictionaries welcome many new words, and the Internet has become one of the biggest sources of them. A ''selfie'', for example, is a photo that you take of yourself, usually with a mobile phone. A ''netizen'' is a citizen who spends much of their life online. The language people type to one another online is often rather different from the language used elsewhere. To save time, friends shorten common phrases: ''BRB'' means ''be right back'', and ''COZ'' is a quick way of writing ''because''. These short forms can be clear and friendly among people who know them. However, before you use them, it is wise to stop and think about who will read your message. An older reader, or a teacher, may have no idea what you intend to say. Make sure that any abbreviations and emojis you choose really suit the situation, or your clever message may only cause confusion.', '说明·网络时代的新词', 153, '[{"q":"What is a ''netizen'', according to the passage?","answer":"D","options":["A new kind of mobile phone.","A photo taken of yourself.","A printed dictionary.","A person who spends a lot of time living online."],"explanation":"原文解释 netizen 是大量时间在网上的公民,为转述。"},{"q":"Why do online friends use short forms like ''BRB'' and ''COZ''?","answer":"A","options":["To save time while typing.","To make their messages longer.","To hide what they mean from friends.","To follow a school rule."],"explanation":"原文说为了省时间而缩短常用短语,为转述。"},{"q":"What advice does the writer give before using abbreviations?","answer":"B","options":["Always use as many as possible.","Think about whether your reader will understand them.","Never write any messages at all.","Use them only with teachers."],"explanation":"原文建议先想想谁会读、是否合适,为转述。"}]'::jsonb, '[{"word":"selfie","cn":"自拍"},{"word":"netizen","cn":"网民"}]'::jsonb, 2, 'required1', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Lost on the First Floor', 'When I first visited New York, I went to a downtown shopping centre to buy some winter boots. At the entrance, I asked a friendly lady where the shoe section was, and she told me it was on the first floor. So I climbed the stairs and searched everywhere, but I could not find a single pair of boots. Feeling rather puzzled, I decided to give up and look for the exit. On my way out, I was surprised to see that the shoes were actually sold downstairs, on the ground floor. At first I thought the lady had given me wrong information. Later, a friend explained the real reason. In American English, the ''first floor'' is the floor at ground level, but in British English, the same words mean the floor above it. The lady had been perfectly correct; I had simply understood her in the British way. It was a small misadventure, but I never forgot it.', '记叙·一次英语误会', 159, '[{"q":"Why could the writer not find the boots upstairs?","answer":"C","options":["The shop had already closed.","The lady had lied to the writer.","The shoes were sold on the ground floor instead.","There were no shoes in the whole shop."],"explanation":"原文说鞋其实在底层(ground floor)卖,为转述。"},{"q":"What was the real cause of the misunderstanding?","answer":"D","options":["The writer could not speak any English.","The lady pointed the wrong way on purpose.","The shopping centre had no signs.","''First floor'' means different levels in American and British English."],"explanation":"原文解释 first floor 在英美英语里指不同楼层,为转述。"},{"q":"How did the writer finally feel about the lady?","answer":"A","options":["That she had actually been right all along.","That she had wanted to trick him.","That she knew nothing about the shop.","That she was rude and unhelpful."],"explanation":"原文说那位女士其实完全正确,是自己理解错了,为转述。"}]'::jsonb, '[{"word":"ground floor","cn":"(英)一层,底层"}]'::jsonb, 2, 'required1', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Expressions That Trick You', 'Some English expressions seem clear but really mean something quite different, and they can easily trick a learner. If a teacher says she has ''a frog in her throat'', she has not eaten a frog; she simply cannot speak clearly because her throat feels dry. When someone has ''green fingers'', it does not mean their hands are green; it means they are very good at growing plants. If a friend tells you to ''pull up your socks'', they are not talking about your clothes at all, but asking you to try harder. And in Britain, the comment ''Not bad'' can be high praise. It often means something is rather good, better than the speaker expected. A Chinese student once felt upset to read ''Not bad'' on his perfect paper, until he learned what it really meant. The lesson is simple: behind many everyday expressions there is a hidden meaning, so it is always wise to ask if you are unsure.', '说明·容易误解的英语表达', 160, '[{"q":"What does it mean if someone has ''a frog in her throat''?","answer":"B","options":["She has just eaten a frog.","She finds it hard to speak clearly for a while.","She is very good at swimming.","She has a pet frog at home."],"explanation":"原文解释这是因喉咙干而说话困难,为转述。"},{"q":"What does ''pull up your socks'' actually ask someone to do?","answer":"C","options":["To fix their clothes.","To buy new socks.","To make a greater effort.","To sit down and rest."],"explanation":"原文说该表达是叫人更努力,为转述。"},{"q":"Why was the Chinese student upset about ''Not bad''?","answer":"D","options":["He had failed the whole paper.","His teacher had made many errors.","He could not read the comment.","He did not realise it could be real praise."],"explanation":"原文说他不知道 Not bad 其实是表扬,为转述。"}]'::jsonb, '[{"word":"green fingers","cn":"园艺高手"},{"word":"praise","cn":"表扬"}]'::jsonb, 2, 'required1', 'U2', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'A Boy and His Hamburger', 'One afternoon my little brother held up his lunch and asked me a very (1)____ question: was there really ham inside a hamburger? I started to laugh, because of course there (2)____. His question made me notice how (3)____ English can be. There is no egg in an eggplant, and a pineapple has neither pine nor apple in it. The more examples I thought of, the more (4)____ they seemed. We sculpt a sculpture, but we just (5)____ a photo. We say it is (6)____ when water falls from the sky, yet we never say it is ''sunshining''. I told my brother that English was (7)____ by people, not by computers, so it is full of surprises. He listened with wide eyes and then asked another funny (8)____. That evening I realised that his simple questions had (9)____ me to look at my own language in a new way. Sometimes a child can (10)____ you something important.', 157, 2, '[{"q":"1","answer":"A","options":["odd","tall","warm","rich"],"explanation":"a very odd question 一个很奇怪的问题。"},{"q":"2","answer":"B","options":["did","wasn''t","will","can"],"explanation":"回答 was there...? 的省略 → there wasn''t。"},{"q":"3","answer":"C","options":["boring","quiet","confusing","heavy"],"explanation":"how confusing English can be 英语多令人困惑。"},{"q":"4","answer":"D","options":["easy","useful","safe","strange"],"explanation":"越想越觉得 strange 奇怪。"},{"q":"5","answer":"A","options":["take","make","do","give"],"explanation":"take a photo 固定搭配。"},{"q":"6","answer":"B","options":["shining","raining","burning","ringing"],"explanation":"天上落水 → it is raining 在下雨。"},{"q":"7","answer":"C","options":["eaten","sold","created","lost"],"explanation":"was created by people 由人创造。"},{"q":"8","answer":"D","options":["answer","price","machine","question"],"explanation":"asked another question 又问一个问题。"},{"q":"9","answer":"A","options":["helped","stopped","refused","forced"],"explanation":"helped me to look 帮我去看。"},{"q":"10","answer":"B","options":["buy","teach","throw","hide"],"explanation":"teach you something 教你一些东西。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'My First Day with American Words', 'On my first day in New York, I quickly learned that American and British English are not the (1)____. When my host asked me to put ''gas'' in the car, I was (2)____, because in Britain we call it petrol. Then he said we would drive along the (3)____, which I knew as the motorway at home. Later we took the (4)____ to the top of a tall building; my family in London would have said ''lift''. To get across the city, we rode the (5)____, but in the UK people travel on the underground. That night I went back to my small (6)____, the kind of home an American would call an apartment. So many everyday (7)____ were different that my head was spinning. Luckily, my host could always guess my (8)____ from the situation, so we never had any real (9)____. By the end of the week, I could even (10)____ the two kinds of English apart, and the whole thing felt like a fun game.', 168, 2, '[{"q":"1","answer":"C","options":["best","first","same","last"],"explanation":"not the same 不一样。"},{"q":"2","answer":"D","options":["happy","tired","proud","confused"],"explanation":"I was confused 我很困惑。"},{"q":"3","answer":"A","options":["highway","doorway","railway","runway"],"explanation":"美式 highway = 英式 motorway。"},{"q":"4","answer":"B","options":["stairway","elevator","engine","ladder"],"explanation":"美式 elevator = 英式 lift。"},{"q":"5","answer":"C","options":["highway","boat","subway","plane"],"explanation":"美式 subway = 英式 underground。"},{"q":"6","answer":"D","options":["shop","office","garden","flat"],"explanation":"英式 flat = 美式 apartment。"},{"q":"7","answer":"A","options":["words","songs","prices","games"],"explanation":"everyday words 日常词汇。"},{"q":"8","answer":"B","options":["weather","meaning","price","age"],"explanation":"guess my meaning 猜我的意思。"},{"q":"9","answer":"C","options":["money","fun","trouble","rest"],"explanation":"any real trouble 真正的麻烦。"},{"q":"10","answer":"D","options":["throw","sell","lose","tell"],"explanation":"tell ... apart 区分。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'Building Words Like Blocks', 'My English teacher once told us that making new words is a bit like (1)____ with blocks. Many long words are simply (2)____ from shorter ones we already know. The first way, she said, is to (3)____ two words together, so ''home'' and ''work'' give us ''homework''. The second way is to add a (4)____ or a suffix. If we put ''un-'' in front of ''happy'', the new word means the (5)____. If we add ''-ment'' to ''improve'', we get a (6)____ called ''improvement''. The third way is to use a word as a different (7)____ of speech, the way we ''water'' the plants. Once I understood these (8)____, reading became much easier. Whenever I met an (9)____ word, I broke it into parts and tried to guess its meaning. My teacher was right: knowing how words are built can really (10)____ you when you read.', 146, 2, '[{"q":"1","answer":"A","options":["building","sleeping","running","cooking"],"explanation":"like building with blocks 像搭积木。"},{"q":"2","answer":"B","options":["sold","made","eaten","lost"],"explanation":"made from shorter ones 由更短的词构成。"},{"q":"3","answer":"C","options":["break","throw","join","hide"],"explanation":"join two words 把两个词合在一起。"},{"q":"4","answer":"D","options":["price","noise","season","prefix"],"explanation":"a prefix or a suffix 前缀或后缀。"},{"q":"5","answer":"A","options":["opposite","machine","garden","market"],"explanation":"un- 使词义 opposite 相反。"},{"q":"6","answer":"B","options":["price","noun","song","city"],"explanation":"-ment 构成 noun 名词。"},{"q":"7","answer":"C","options":["piece","kind","part","side"],"explanation":"a different part of speech 不同词性。"},{"q":"8","answer":"D","options":["prices","noises","tickets","patterns"],"explanation":"understood these patterns 懂得这些规律。"},{"q":"9","answer":"A","options":["unfamiliar","easy","empty","early"],"explanation":"an unfamiliar word 陌生的词。"},{"q":"10","answer":"B","options":["stop","help","lose","sell"],"explanation":"can really help you 真的能帮你。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'Chatting with My Online Friend', 'Last year I made a foreign friend on a learning (1)____, and we often chat online in English. At first, his messages were full of short forms that I could not (2)____. When he typed ''BRB'', I had no idea he meant ''be right (3)____''. He also used ''COZ'' instead of ''because'', just to (4)____ time. Slowly, I got used to this kind of (5)____ language and even started to use it myself. But my friend gave me one piece of good (6)____: before sending such words, I should think about who would (7)____ them. With close friends they are clear and friendly, but a teacher might not (8)____ what I mean. So now I am more (9)____ of my reader. Learning to chat online has not only improved my English; it has also (10)____ me that the right words depend on the right situation.', 145, 2, '[{"q":"1","answer":"C","options":["garden","market","forum","kitchen"],"explanation":"a learning forum 学习论坛。"},{"q":"2","answer":"D","options":["sell","throw","eat","understand"],"explanation":"could not understand 看不懂。"},{"q":"3","answer":"A","options":["back","down","off","away"],"explanation":"be right back 马上回来。"},{"q":"4","answer":"B","options":["waste","save","lose","spend"],"explanation":"save time 节省时间。"},{"q":"5","answer":"C","options":["formal","ancient","informal","foreign"],"explanation":"informal language 非正式语言。"},{"q":"6","answer":"D","options":["noise","price","weather","advice"],"explanation":"a piece of good advice 一条好建议。"},{"q":"7","answer":"A","options":["read","cook","drive","throw"],"explanation":"who would read them 谁会读。"},{"q":"8","answer":"B","options":["buy","know","sell","lose"],"explanation":"might not know what I mean 可能不懂。"},{"q":"9","answer":"C","options":["afraid","tired","aware","free"],"explanation":"more aware of my reader 更留意读者。"},{"q":"10","answer":"D","options":["stopped","sold","lost","taught"],"explanation":"has taught me 教会了我。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'A Surprising Dinner', 'Last summer I stayed with a kind British (1)____. One evening, the mother smiled and said we would have ''toad-in-the-hole'' for (2)____. I was really (3)____, because I thought a toad was a kind of animal like a frog. Why would anyone (4)____ a toad? I did not want to be (5)____, so I said nothing and waited nervously. To my (6)____, the dish turned out to be sausages baked in a kind of cake, and it was (7)____! Everyone laughed when I explained what I had (8)____ at first. The funny name had completely (9)____ me. After that night, I learned never to judge an English dish by its strange (10)____, and I happily tried everything the family offered.', 120, 2, '[{"q":"1","answer":"A","options":["family","garden","machine","market"],"explanation":"a British family 英国家庭。"},{"q":"2","answer":"B","options":["morning","dinner","summer","music"],"explanation":"for dinner 当晚饭。"},{"q":"3","answer":"C","options":["bored","sleepy","surprised","angry"],"explanation":"I was really surprised 我很惊讶。"},{"q":"4","answer":"D","options":["buy","sell","wash","eat"],"explanation":"why would anyone eat a toad 为何要吃。"},{"q":"5","answer":"A","options":["rude","kind","early","rich"],"explanation":"did not want to be rude 不想失礼。"},{"q":"6","answer":"B","options":["price","surprise","noise","weather"],"explanation":"to my surprise 令我惊讶的是。"},{"q":"7","answer":"C","options":["terrible","empty","delicious","quiet"],"explanation":"it was delicious 很美味。"},{"q":"8","answer":"D","options":["sold","thrown","lost","thought"],"explanation":"what I had thought 我之前的想法。"},{"q":"9","answer":"A","options":["fooled","helped","saved","paid"],"explanation":"had completely fooled me 把我骗了。"},{"q":"10","answer":"B","options":["price","name","size","colour"],"explanation":"by its strange name 凭奇怪的名字。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U2', 'Learning Tricky Expressions', 'My favourite English lesson was the day our teacher taught us some (1)____ expressions that do not mean what they seem. She said that if someone has ''a frog in their (2)____'', it does not mean they ate a frog; they just cannot speak (3)____ for a moment. If a friend has ''green fingers'', their hands are not really (4)____; they are simply good at growing (5)____. When your mother tells you to ''pull up your (6)____'', she is not talking about your clothes; she wants you to try (7)____. The teacher also warned us that in Britain, the (8)____ ''Not bad'' is often real praise. It can mean something is rather (9)____, better than expected. I wrote all these expressions down, because I did not want a hidden meaning to (10)____ me one day.', 135, 2, '[{"q":"1","answer":"C","options":["easy","empty","tricky","quiet"],"explanation":"tricky expressions 棘手的表达。"},{"q":"2","answer":"D","options":["garden","pocket","window","throat"],"explanation":"a frog in their throat 喉咙里有只青蛙。"},{"q":"3","answer":"A","options":["clearly","loudly","slowly","softly"],"explanation":"cannot speak clearly 说不清楚。"},{"q":"4","answer":"B","options":["warm","green","wet","cold"],"explanation":"hands are not really green 手并非真绿。"},{"q":"5","answer":"C","options":["cars","books","plants","coins"],"explanation":"good at growing plants 擅长种植。"},{"q":"6","answer":"D","options":["shoes","books","bags","socks"],"explanation":"pull up your socks 振作努力。"},{"q":"7","answer":"A","options":["harder","later","louder","slower"],"explanation":"try harder 更努力。"},{"q":"8","answer":"B","options":["price","comment","noise","machine"],"explanation":"the comment ''Not bad'' 这句评论。"},{"q":"9","answer":"C","options":["wrong","empty","good","free"],"explanation":"rather good 相当不错。"},{"q":"10","answer":"D","options":["help","pay","save","trick"],"explanation":"a hidden meaning to trick me 误导我。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Looking for the Lift', '外研社版必修第一册 U2 · dialogue', 3, 'Mia: Excuse me, where can I find the lift to the top floor?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Three Ways to Make Words', '外研社版必修第一册 U2 · passage', 2, 'English makes new words in several simple ways.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 What Does BRB Mean?', '外研社版必修第一册 U2 · dialogue', 3, 'Leo: My online friend just typed ''BRB''. What does that mean?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 A Crazy Language', '外研社版必修第一册 U2 · passage', 2, 'English can be a really funny language to learn.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 A Frog in the Throat', '外研社版必修第一册 U2 · dialogue', 3, 'Tom: Our teacher Maggie couldn''t teach today. She had a frog in her throat.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Choose Your Words Online', '外研社版必修第一册 U2 · passage', 2, 'The language we use online is often different from other English.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Story about a Misunderstanding in English(写一个英语误会的小故事)', 'A Misunderstanding in English', '假设你叫李华,去年暑假你住在一个英国家庭。请用英语写一个约80词的小故事,内容包括:① 故事中的人物和地点;② 发生了什么(一个由英语词语引起的误会);③ 误会是怎么解开的、你的感受。可用 ''I was really surprised when…'', ''It turned out that…'' 等表达。', 'Suppose you are Li Hua. Last summer you stayed with a British family. Write a short story (about 80 words) including: 1) who was in the story and where it happened; 2) what happened — a misunderstanding caused by an English word; 3) how the misunderstanding was cleared up and how you felt. You may use ''I was really surprised when…'' and ''It turned out that…''.', '["交代人物与地点(Last summer, I stayed with a British family.)","描述误会(I was really surprised when … / I wasn''t sure whether …)","解开误会(It turned out that …)","表达感受、句句围绕这个误会"]'::jsonb, 70, 100, 'Last summer, I stayed with a British family. One evening, the mother said we would have ''toad-in-the-hole'' for dinner. I was really surprised, because I thought a toad was an animal like a frog. I wasn''t sure whether I should eat it, so I said nothing. It turned out that the dish was just sausages baked in a kind of cake, and it was delicious! Everyone laughed when I explained my mistake. That funny misadventure taught me never to judge an English dish by its strange name.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I was really surprised when the mother said we would have ''toad-in-the-hole''.","I wasn''t sure whether I should eat it, so I said nothing.","It turned out that the dish was just sausages baked in a kind of cake.","That funny misadventure taught me never to judge an English dish by its strange name."]'::jsonb, '[{"wrong":"I was surprised when she say that.","correct":"I was surprised when she said that.","note":"记叙过去的事,从句动词用过去式 said。"},{"wrong":"It turned out that the dish is sausages.","correct":"It turned out that the dish was sausages.","note":"主句过去时,宾语从句也用过去时保持一致。"},{"wrong":"I wasn''t sure whether eat it or not.","correct":"I wasn''t sure whether to eat it or not.","note":"whether 后接动词不定式用 whether to do。"}]'::jsonb, '【英语误会小故事结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U2', '{"title":"构词法·派生 / 合成 / 转化 速查","intro":"英语靠三种方式不断造新词:派生(加前后缀)、合成(两词合一)、转化(同词作不同词性)。懂得规律,就能拆词猜义、读得更快。判断口诀:看词的两端有没有前后缀(派生)→ 看是不是两个词拼起来(合成)→ 看它是不是不变形换了词性(转化)。","table":{"headers":["构词方式","做法 / 例子"],"rows":[["派生·前缀","un-/in-/im-/dis- 多表否定:correct→incorrect,happy→unhappy,possible→impossible"],["派生·后缀","-less(没有)/-ful(充满):harmless / harmful;-ment/-ity/-ness 构成名词:improve→improvement;-ly 构成副词:quick→quickly"],["合成","两个词合一,意思常可推出:home+work=homework,black+board=blackboard,sub+way=subway,sea+sick=seasick"],["转化","同一拼写换词性,多为名/形→动:water(水→浇水)、name(名字→命名)、calm(平静的→使平静)、empty(空的→倒空)"]]},"specialRules":[{"rule":"前缀一般改变词义(常表否定),不改变词性","mark":"happy(形)→ unhappy(仍是形)"},{"rule":"后缀常改变词性:-ment/-ness/-ity→名词,-ly→副词,-ful/-less/-ive→形容词","mark":"improve(动)→ improvement(名)"},{"rule":"-less 表''没有'',-ful 表''充满'',构成一对:harmless / harmful、useless / useful","mark":"意义相反,别选反"},{"rule":"转化后仍按句子需要选动词形式:to / 情态动词 / 祈使句后用原形","mark":"Remember to water the flowers."}],"why":["新词大多由简单词搭建而来:认出前后缀、拆出合成的两半、辨出换了词性的同一个词,就能不查词典也大致猜出意思。"],"gaokaoPoints":["语法填空高频:给词 improve / care,按空位填 improvement / careful 等正确派生形式。","完形与阅读:用前后缀判断生词的褒贬与词义(harmless 好 vs harmful 坏)。","读后续写/写作:用转化词让表达更地道(water the plants, text a friend, name the baby)。"],"examVsReal":[{"exam":"improve → improvement（考试填名词形式）","real":"口语里也常直接说 I''ve got better.","note":"考试看空位词性填派生词;真实表达更灵活"},{"exam":"It is going to rain.（rain 用作动词）","real":"也可说 There''s going to be rain.（rain 用作名词）","note":"同一个词既能作动词又能作名词,转化在生活中随处可见"}]}'::jsonb, 'fltrp');
